// Sarvam AI on the business's own key: speech to text and back in Indian languages, translation and
// transliteration, cloned voices, chat models, dubbing, document translation and digitising, plus Voice
// Agents (deployments, campaigns, outbound calls, call analytics, boards, tests). actions.json is generated by
// `bun scripts/openapi-actions.ts sarvam`; COVERAGE.md says what's left out.
import { AppFile } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";

const api: Api = {
  name: "Sarvam",
  base: "https://api.sarvam.ai",
  tokenHelp: "dashboard.sarvam.ai → API keys",
  // the model APIs read api-subscription-key, Voice Agents X-API-Key
  auth: (key) => ({ "api-subscription-key": key, "X-API-Key": key }),
  // a bad key is a 403 invalid_api_key_error
  deadToken: (status, body) => status === 401 || status === 403 && /api.?key/i.test(JSON.stringify(body?.error ?? "")),
};

const actions = await specActions(new URL("./actions.json", import.meta.url), api);

// speech comes back as base64 WAVs in JSON; hand them over as files the agent can send on
for (const name of ["text_to_speech", "text_to_speech_cloned_voice"]) {
  const a = actions[name]!;
  const run = a.run;
  a.run = async (i, key) => {
    const out = (await run(i, key)) as { audios?: string[] };
    if (!Array.isArray(out?.audios)) return out;
    const audios = out.audios.map((b64, n) => new AppFile(`speech-${n + 1}.wav`, "audio/wav", Buffer.from(b64, "base64")));
    return { ...out, audios };
  };
}

export const sarvam: OwnApp = {
  app: "sarvam",
  name: "Sarvam AI",
  logo: "/logos/sarvam.svg",
  keyField: {
    label: "API key",
    help: "dashboard.sarvam.ai → API keys (Voice Agents: Settings → API Key). Calls are billed to your Sarvam account.",
    placeholder: "sk_…",
  },
  async check(key) {
    await call(api, key, { method: "GET", path: "/voices", query: [], headers: [] }, {});
  },
  actions,
};
